-- ============================================================
-- Extraction base Microsoft Works (.wdb) -> SQL
-- Genere automatiquement - voir README dans le classeur Excel
-- pour le detail de la methodologie et les colonnes deduites.
-- Compatible SQLite / MySQL / PostgreSQL (types generiques TEXT/INTEGER/REAL)
-- ============================================================

DROP TABLE IF EXISTS serologie_visas_actuel;
CREATE TABLE serologie_visas_actuel (
    ID_Ligne_Source VARCHAR(20) PRIMARY KEY,
    Doublon_exact VARCHAR(3),
    Date TEXT,
    Numero_Dossier TEXT,
    Prescripteur TEXT,
    Motif_Origine TEXT,
    Nom_Patient TEXT,
    Test_HIV_1 TEXT,
    Test_HIV_2 TEXT,
    Test_HIV_3 TEXT,
    Interpretation_HIV TEXT,
    Resultat_TPHA TEXT,
    Titre_TPHA TEXT,
    Resultat_VDRL TEXT,
    Titre_VDRL TEXT,
    Commentaire_Conclusion TEXT,
    Age TEXT,
    Age_annees REAL,
    Numero_Dossier_Valeur REAL
);
















